def unique_cands(S,pts):
 Ts=[]
 for f in transforms:
  q=[f(*p) for p in S]; mr=min(r for r,c in q); mc=min(c for r,c in q); t=frozenset((r-mr,c-mc) for r,c in q)
  if t not in Ts: Ts.append(t)
 out=set()
 for oi,t in enumerate(Ts):
  for p in pts:
   for q in t:
    a=(p[0]-q[0],p[1]-q[1])
    if all((x-a[0],y-a[1]) in t for x,y in pts): out.add((oi,a))
 return Ts,sorted(out,key=lambda x:(x[1][0],x[1][1],x[0]))
